use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-late-y176";
fn read(p:String)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert_eq!(read(format!("{R}/link-runs/result.json"))["status"],"complete");for label in["off","on"]{let info=read(format!("{R}/artifacts-{label}.json"));let cmd=read(format!("{R}/link-runs/link-{label}/command.json"));for arg in["-O","target-cpu=native","lto=fat","codegen-units=1"]{assert!(cmd["argv"].as_array().unwrap().contains(&json!(arg)));}let mut pins:BTreeMap<String,String>=serde_json::from_value(info["input_pins"].clone()).unwrap();for n in["probe.rs","perf.rs"]{let p=format!("{R}/{n}");pins.insert(p.clone(),hash(&p));}let binary=format!("{R}/{label}-probe");let output=json!({"binary":binary,"sha256":hash(&binary),"input_pins":pins,"native_flags":info["rustflags"],"lto":"fat","library_manifest":info});fs::write(format!("{R}/probe-{label}.json"),serde_json::to_vec_pretty(&output).unwrap()).unwrap();}println!("Sealed optimizedlink-runs probes; argvO/native/fatLTO/CGU1 inspected");}
